import { test, expect } from '@playwright/test';

test.describe('Modal Dialog Focus Restoration', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/modal-dialog');
  });

  test('should restore focus to trigger button after modal closes', async ({ page }) => {
    // Open modal by clicking trigger button
    const triggerButton = page.getByRole('button', { name: /open modal/i });
    await triggerButton.click();

    // Verify modal is visible
    const modal = page.locator('[data-testid="modal-dialog"]');
    await expect(modal).toBeVisible();

    // Verify modal content is visible
    const modalContent = page.getByRole('region', { name: /modal content/i });
    await expect(modalContent).toBeVisible();

    // Verify close button is visible and enabled
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify trigger button is not focused
    await expect(triggerButton).not.toBeFocused();

    // Close modal by clicking close button
    await closeButton.click();

    // Verify modal is closed
    await expect(modal).not.toBeVisible();

    // Verify focus is restored to trigger button
    await expect(triggerButton).toBeFocused();

    // Verify modal button is now disabled
    await expect(closeButton).toBeDisabled();
  });

  test('should handle focus restoration when modal is closed programmatically', async ({ page }) => {
    // Open modal by clicking trigger button
    const triggerButton = page.getByRole('button', { name: /open modal/i });
    await triggerButton.click();

    // Verify modal is visible
    const modal = page.locator('[data-testid="modal-dialog"]');
    await expect(modal).toBeVisible();

    // Verify modal content is visible
    const modalContent = page.getByRole('region', { name: /modal content/i });
    await expect(modalContent).toBeVisible();

    // Verify close button is visible and enabled
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify trigger button is not focused
    await expect(triggerButton).not.toBeFocused();

    // Close modal programmatically
    const closePromise = page.waitForResponse(response => response.url().includes('/api/modal/close'));
    await closePromise;

    // Verify modal is closed
    await expect(modal).not.toBeVisible();

    // Verify focus is restored to trigger button
    await expect(triggerButton).toBeFocused();

    // Verify close button is now disabled
    await expect(closeButton).toBeDisabled();
  });
});
